True def transform(grid):
    """Complete the outer rectangle and any dense horizontal strokes."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    markers = [v for v in counts if v not in (background, 2)]
    if not markers:
        return [row[:] for row in grid]
    marker = max(markers, key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == marker]
    if not points:
        return [row[:] for row in grid]
    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)
    out = [row[:] for row in grid]

    # Close the global bounding rectangle.
    for r in (rmin, rmax):
        for c in range(cmin, cmax + 1):
            if out[r][c] == background:
                out[r][c] = 2
    for c in (cmin, cmax):
        for r in range(rmin, rmax + 1):
            if out[r][c] == background:
                out[r][c] = 2

    # Dense horizontal rows are additional intended strokes.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out
